// The sources library: every source cited anywhere in the data, grouped by publisher,
// with how many entries rely on it. Built from the already-loaded data (no extra fetch)
// and loaded on first use, like the About dialog.

import type { Place } from '../data/placeTypes.ts';
import type { HistoricalEvent, Source } from '../data/types.ts';
import { el, externalLink } from '../dom.ts';

interface Counted {
  source: Source;
  uses: number;
}

export function collectSources(events: readonly HistoricalEvent[], places: readonly Place[]): Map<string, Counted[]> {
  const byKey = new Map<string, Counted>();
  const add = (source: Source): void => {
    const key = `${source.publisher}|${source.title}|${source.url}`;
    const hit = byKey.get(key);
    if (hit) hit.uses += 1;
    else byKey.set(key, { source, uses: 1 });
  };
  for (const event of events) for (const source of event.sources) add(source);
  for (const place of places) {
    for (const name of place.names) for (const source of name.sources) add(source);
    for (const source of place.earliest?.sources ?? []) add(source);
  }
  const groups = new Map<string, Counted[]>();
  for (const counted of byKey.values()) {
    const list = groups.get(counted.source.publisher) ?? [];
    list.push(counted);
    groups.set(counted.source.publisher, list);
  }
  for (const list of groups.values()) list.sort((a, b) => b.uses - a.uses || a.source.title.localeCompare(b.source.title));
  return groups;
}

let dialog: HTMLDialogElement | null = null;

function build(groups: ReadonlyMap<string, Counted[]>): HTMLDialogElement {
  const node = el('dialog', 'about sources');
  node.setAttribute('aria-labelledby', 'sources-title');

  const title = el('h2', 'about__title', 'Sources library');
  title.id = 'sources-title';
  const total = [...groups.values()].reduce((n, list) => n + list.length, 0);
  const intro = el(
    'p',
    '',
    `Every source cited in this map's data: ${total.toLocaleString('en-US')} distinct works and pages, grouped by publisher. The number after each is how many entries rely on it. The sourcing rules are described in the About dialog.`,
  );

  const list = el('div', 'sources__list');
  const publishers = [...groups.entries()].sort((a, b) => b[1].length - a[1].length || a[0].localeCompare(b[0]));
  for (const [publisher, counted] of publishers) {
    const item = el('details', 'myths__item');
    const uses = counted.reduce((n, c) => n + c.uses, 0);
    const head = el('summary', 'myths__claim');
    head.append(publisher, el('span', 'card__muted', ` · ${counted.length.toLocaleString('en-US')} works, ${uses.toLocaleString('en-US')} citations`));
    const entries = el('ul', 'card__list sources__entries');
    for (const { source, uses: n } of counted) {
      const line = el('li');
      line.append(externalLink(source.url, source.title));
      const detail = [source.author, source.pages].filter(Boolean).join(', ');
      line.append(el('span', 'card__muted', `${detail === '' ? '' : ` — ${detail}`} (${n.toLocaleString('en-US')})`));
      entries.append(line);
    }
    item.append(head, entries);
    list.append(item);
  }

  const close = el('button', 'btn about__close', 'Close');
  close.type = 'button';
  close.addEventListener('click', () => node.close());

  node.append(title, intro, list, close);
  node.addEventListener('click', (e) => {
    if (e.target === node) node.close();
  });
  document.body.append(node);
  return node;
}

export function openSources(events: readonly HistoricalEvent[], places: readonly Place[]): void {
  if (!dialog) dialog = build(collectSources(events, places));
  dialog.showModal();
}
